import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining a skewed quadratic bowl with sinusoidal modulation and pairwise interactions to approximate target ELA features.

    Formula:
    f(x) = quadratic_bowl(x) + skew(x) + modulation(x) + interaction(x)

    Components:
    - quadratic_bowl(x): Creates a quadratic bowl shape.
    - skew(x): Introduces skewness to the fitness distribution.
    - modulation(x): Adds sinusoidal modulation for ruggedness.
    - interaction(x): Implements pairwise interactions affecting the linear and quadratic meta-models.
    """
    def quadratic_bowl(x):
        return np.sum(x**2)

    def skew(x):
        return 0.417 * np.sum(x**3) / (1 + np.std(x)**2)

    def modulation(x):
        return np.sum(np.sin(2*x)) * 0.1

    def interaction(x):
        interaction_sum = 0
        for i in range(len(x)):
            for j in range(i + 1, len(x)):
                interaction_sum += x[i] * x[j] * 0.2
        return interaction_sum



    return quadratic_bowl(x) + skew(x) + modulation(x) + interaction(x)
